output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper is obliged to take the entrance cart at the cart bay before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": "at(1,5)",
        "entrance_cart_present": "cartAt(1,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "entrance_cart_present",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_passing_cart_bay_empty_handed",
    "text": "A shopper at the entrance cart bay with a cart available is forbidden to move away without first taking the cart.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": "at(1,5)",
        "entrance_cart_present": "cartAt(1,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "leave_cart_bay_without_taking_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "entrance_cart_present",
              {
                "not": "with_cart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "not": "with_cart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_bay_without_taking_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Items must be placed into a cart rather than carried by hand.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "with_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        },
        "item_pickup_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "with_cart"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cartless_item_pickup",
          "carrying_by_hand"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After taking any shelf item while using a cart, the shopper is obliged to return the cart to the service counter area.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "cart_return_cell": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "item_taken_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "with_cart"
            ]
          },
          "post": "with_cart"
        },
        "return_cart_to_counter": {
          "pre": {
            "and": [
              "cart_return_cell",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken_with_cart",
      "discharge": "return_cart_to_counter"
    }
  },
  {
    "id": "leave_cart_only_at_counter",
    "text": "A shopper is forbidden to leave a cart anywhere except at the designated counter cell.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "cart_return_cell": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_counter": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART",
              {
                "not": "cart_return_cell"
              }
            ]
          },
          "post": null
        },
        "proper_cart_return": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART",
              "cart_return_cell"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_counter"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden to exit the store while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        },
        "pedestrian_exit": {
          "pre": {
            "and": [
              "exit_cell",
              {
                "not": "with_cart"
              },
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "Once the cart has been returned to the counter, the shopper is obliged to leave through the exit without the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "cart_return_cell": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)",
        "exit_cell": "at(9,5)",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_cell",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        },
        "exit_as_pedestrian": {
          "pre": {
            "and": [
              "exit_cell",
              "without_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned",
      "discharge": "exit_as_pedestrian"
    }
  },
  {
    "id": "no_cart_in_eastern_shelf_end",
    "text": "Carts are forbidden from being pushed beyond the egg endcap into the eastern blocked shelf-end area.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "egg_endcap_cell": "at(6,4)",
        "restricted_eastern_shelf_end": {
          "or": [
            "at(7,4)",
            "at(8,4)"
          ]
        },
        "cart_in_restricted_eastern_shelf_end": {
          "and": [
            "with_cart",
            "restricted_eastern_shelf_end"
          ]
        }
      },
      "events": {
        "push_cart_deeper_from_egg_endcap": {
          "pre": {
            "and": [
              "egg_endcap_cell",
              "with_cart",
              {
                "or": [
                  "E",
                  "S"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "push_cart_deeper_from_egg_endcap",
          "cart_in_restricted_eastern_shelf_end"
        ]
      }
    }
  }
]
